contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public entry that performs the test. Send wei via weiToSend.
    function run(uint256 weiToSend) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (weiToSend)); require(weiToSend <= 1000000000000000000000000000000);
        require(address(this).balance >= weiToSend);

        // Observe before-state
        uint256 totalDistributedBefore = c.totalDistributed(); if (__ESBMC_reverted()) return;
        uint256 balBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        bool blackBefore = c.blacklist(address(this)); if (__ESBMC_reverted()) return;

        // Attempt the state-changing call and record whether it reverted
        bool reverted;
        c.getTokens{value: weiToSend}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Observe after-state
        uint256 totalDistributedAfter = c.totalDistributed(); if (__ESBMC_reverted()) return;
        uint256 balAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        bool blackAfter = c.blacklist(address(this)); if (__ESBMC_reverted()) return;

        // Single general assertion covering both reverted and non-reverted cases.
        // If not reverted: blackAfter must be true, and balance increase equals totalDistributed increase.
        // If reverted: none of the three observed values changed.
        assert(
            (!reverted && blackAfter == true && balAfter >= balBefore && totalDistributedAfter >= totalDistributedBefore && (balAfter - balBefore) == (totalDistributedAfter - totalDistributedBefore))
            ||
            (reverted && totalDistributedAfter == totalDistributedBefore && balAfter == balBefore && blackAfter == blackBefore)
        );
    }

    receive() external payable {}
}

