        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= weiToSend);
        uint256 totalDistributedBefore;
        try c.totalDistributed() returns (uint256 __r) { totalDistributedBefore = __r; } catch { return; }
        uint256 balBefore;
        try c.balanceOf(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        bool blackBefore;
        try c.blacklist(address(this)) returns (bool __r) { blackBefore = __r; } catch { return; }
        bool reverted;
        try c.getTokens{value: weiToSend}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 totalDistributedAfter;
        try c.totalDistributed() returns (uint256 __r) { totalDistributedAfter = __r; } catch { return; }
